contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmt > 0 && collectAmt > 0 && depositAmt < type(uint256).max / 2 && collectAmt <= depositAmt);

        c.Initialized();
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));

        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();

        uint256 balBefore = c.balances(caller);

        bool success;
        vm.prank(caller);
