import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 totalDeposited;
    uint256 totalCollected;

    function setUp() public {
        c = new C();
        c.SetMinSum(0);
        c.Initialized();
        totalDeposited = 0;
        totalCollected = 0;
    }

    function testFuzz_property(
        uint256 depositAmount1,
        uint256 depositAmount2,
        uint256 collectAmount,
        address actor1,
        address actor2
    ) public {
        // Bound to prevent overflow
        vm.assume(depositAmount1 <= type(uint128).max);
        vm.assume(depositAmount2 <= type(uint128).max);
        vm.assume(collectAmount <= type(uint128).max);

        // Actors must be distinct and non-zero (avoid address(0) as caller to prevent confusion, but not strictly required)
        vm.assume(actor1 != actor2);
        vm.assume(actor1 != address(0));
        vm.assume(actor2 != address(0));
        vm.assume(actor1 != address(c));
        vm.assume(actor2 != address(c));

        // Deposit with actor1
        vm.deal(actor1, depositAmount1);
        vm.prank(actor1);
        c.Deposit{value: depositAmount1}();
        totalDeposited += depositAmount1;

        // Deposit with actor2
        vm.deal(actor2, depositAmount2);
        vm.prank(actor2);
        c.Deposit{value: depositAmount2}();
        totalDeposited += depositAmount2;

        // Try collect from actor1 (must have enough balance and >= MinSum=0)
        vm.assume(c.balances(actor1) >= collectAmount);
        uint256 beforeCollectBalanceC = address(c).balance;
        bool success;
        vm.prank(actor1);
        try c.Collect(collectAmount) { success = true; } catch { success = false; }

        if (success) {
            totalCollected += collectAmount;
        }

        // Compute sum of balances of all involved actors and address(0)
        uint256 sumBalances = c.balances(actor1) + c.balances(actor2) + c.balances(address(0));
        uint256 etherBalance = address(c).balance;

        // Reference contract invariant: sum of all tracked balances equals total deposited minus total collected
        assertTrue(sumBalances == totalDeposited - totalCollected);
    }
}

