pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 collectAmt, address depositor1, address depositor2) public {
        // Bound the amounts to a reasonable range and prevent zero deposits
        deposit1 = bound(deposit1, 1, 1e24);
        deposit2 = bound(deposit2, 1, 1e24);
        collectAmt = bound(collectAmt, 1, 1e24);
        vm.assume(depositor1 != depositor2);
        vm.assume(depositor1 != address(0) && depositor2 != address(0));
        vm.assume(depositor1 != address(c) && depositor2 != address(c));

        // Initialize C (required by the original contract)
        c.Initialized();

        // Deposit from two different depositors
        vm.deal(depositor1, deposit1);
        vm.prank(depositor1);
        c.Deposit{value: deposit1}();

        vm.deal(depositor2, deposit2);
        vm.prank(depositor2);
        c.Deposit{value: deposit2}();

        // Set MinSum to something small so Collect can succeed
        vm.prank(address(this));
        c.SetMinSum(0);

        // Collect from depositor1 if they have enough balance
        vm.assume(c.balances(depositor1) >= collectAmt);
        bool ok;
        vm.prank(depositor1);
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        // If Collect succeeded, we check the invariant; if it failed, the invariant is trivially not violated by the bug's specific effect,
        // so we skip the assertion. The fuzzer will find cases where the collect succeeds.
        if (ok) {
            // Invariant: total sum of tracked balances must equal the contract's ether balance
            uint256 totalBalances = c.balances(depositor1) + c.balances(depositor2) + c.balances(address(0));
            uint256 contractBalance = address(c).balance;
            assertTrue(totalBalances == contractBalance);
        }
    }
}

